<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';import{Phone,Mail,Globe}from'lucide-vue-next';import PublicLayout from'../../Layouts/PublicLayout.vue';import type{Settings}from'../../types';const props=defineProps<{settings:Settings}>();const form=useForm({full_name:'',company_name:'',email:'',phone:'',service:'',subject:'',message:'',consent:false,website:''});const submit=()=>form.post('/contact',{preserveScroll:true,onSuccess:()=>form.reset()});</script><template><Head title="Contact Us"><meta name="description" content="Request an IT consultation with MyPro Solutions."/></Head><PublicLayout :settings="settings"><header class="bg-slate-950 py-20 text-white"><div class="wrap"><p class="eyebrow !text-blue-300">Let’s talk</p><h1 class="heading !text-white">How can we make IT simpler?</h1><p class="mt-5 max-w-2xl text-lg text-slate-300">Share your priorities with our solutions team. We’ll review your inquiry and get in touch.</p></div></header><section class="section"><div class="wrap grid gap-12 lg:grid-cols-[360px_1fr]"><aside><h2 class="text-2xl font-extrabold">Contact MyPro</h2><div class="mt-7 grid gap-5"><a :href="`tel:${settings.phone_primary}`" class="flex gap-4"><Phone class="text-brand-600"/><span><b class="block">Telephone</b>{{settings.phone_primary}}<br>{{settings.phone_secondary}}</span></a><a :href="`mailto:${settings.email}`" class="flex gap-4"><Mail class="text-brand-600"/><span><b class="block">Email</b>{{settings.email}}</span></a><a :href="`https://${settings.website}`" class="flex gap-4"><Globe class="text-brand-600"/><span><b class="block">Website</b>{{settings.website}}</span></a></div></aside><form @submit.prevent="submit" class="card grid gap-5 sm:grid-cols-2" novalidate><div><label class="label" for="name">Full name *</label><input id="name" v-model="form.full_name" class="field" required><p class="mt-1 text-sm text-red-600">{{form.errors.full_name}}</p></div><div><label class="label" for="company">Company name</label><input id="company" v-model="form.company_name" class="field"></div><div><label class="label" for="email">Email *</label><input id="email" v-model="form.email" type="email" class="field" required><p class="mt-1 text-sm text-red-600">{{form.errors.email}}</p></div><div><label class="label" for="phone">Mobile or telephone *</label><input id="phone" v-model="form.phone" class="field" required><p class="mt-1 text-sm text-red-600">{{form.errors.phone}}</p></div><div><label class="label" for="service">Service of interest</label><select id="service" v-model="form.service" class="field"><option value="">Select a service</option><option>IT Infrastructure</option><option>Cybersecurity</option><option>Computing Devices</option><option>Managed Services</option><option>Digital Transformation</option></select></div><div><label class="label" for="subject">Subject *</label><input id="subject" v-model="form.subject" class="field" required></div><div class="hidden" aria-hidden="true"><label>Website<input v-model="form.website" tabindex="-1" autocomplete="off"></label></div><div class="sm:col-span-2"><label class="label" for="message">Message *</label><textarea id="message" v-model="form.message" class="field" rows="6" required></textarea><p class="mt-1 text-sm text-red-600">{{form.errors.message}}</p></div><label class="flex gap-3 sm:col-span-2"><input v-model="form.consent" type="checkbox" class="mt-1 h-4 w-4"><span class="text-sm text-slate-600">I consent to MyPro processing my information to respond to this inquiry. *</span></label><p v-if="form.recentlySuccessful" class="sm:col-span-2 rounded-lg bg-green-50 p-4 font-semibold text-green-800">Thank you. Your inquiry has been received.</p><button class="btn-primary sm:col-span-2 sm:w-fit" :disabled="form.processing">{{form.processing?'Sending…':'Send Inquiry'}}</button></form></div></section></PublicLayout></template>
